import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/drafts/page.schema.ts";

test("drafts is refused to someone signed in without documents.edit", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("drafts sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("drafts opens to someone who holds documents.edit", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["documents.edit"] }), "allowed");
});
